return [{ json: {
  // =====================================================
  // CONFIG FOLLOW-UP ANTI-BAN - edite por cliente
  // =====================================================
  imobiliaria: "NOME_DA_IMOBILIARIA",
  supabase_url: "SUA_SUPABASE_URL",
  supabase_anon_key: "SUA_SUPABASE_ANON_KEY",
  tabela_memoria: "leads_memoria_imobiliaria",
  tabela_followups: "followups_imobiliaria",

  // WAHA
  waha_url: "http://waha:3000",
  session: "default",
  waha_api_key: "SUA_API_KEY_WAHA",

  // Anti-ban
  timezone: "America/Asuncion",
  horario_inicio: 8,
  horario_fim: 19,
  max_envios_por_rodada: 8,
  delay_min_segundos: 35,
  delay_max_segundos: 95,
  intervalo_base_por_lead_segundos: 75,

  // Follow-ups ativos
  enviar_followup_2h: true,
  enviar_followup_24h: true,
  enviar_followup_3d: false,

  // Palavras de bloqueio/opt-out
  palavras_bloqueio: ["parar", "cancelar", "não quero", "nao quero", "remover", "sair", "stop", "sem interesse", "já resolvi", "ja resolvi"],

  // Mensagens-base. O Code personaliza usando a memória do lead.
  mensagem_2h_generica: "Conseguiu ver as opções que te mandei? Se quiser, posso te mostrar outras opções também 👌",
  mensagem_24h_generica: "Oi! Passando só pra saber se você ainda está procurando imóvel ou se já resolveu 😊"
}}];

const cfg = $('Config FollowUp').first().json;
const tipo = 'FOLLOWUP_2H';
const minHours = tipo === 'FOLLOWUP_24H' ? 24 : 2;
const flag = tipo === 'FOLLOWUP_24H' ? 'followup_24h_enviado' : 'followup_1_enviado';
const now = new Date();

function hourInTZ(tz) {
  return Number(new Intl.DateTimeFormat('en-US', { timeZone: tz, hour: '2-digit', hour12: false }).format(new Date()));
}
function norm(s) {
  return String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}
function hasBlockWords(lead) {
  const blob = norm(`${lead.resumo_conversa || ''} ${lead.ultimo_motivo || ''} ${lead.ultima_acao || ''} ${lead.etapa_funil || ''}`);
  return (cfg.palavras_bloqueio || []).some(p => blob.includes(norm(p)));
}
function diffHours(dateStr) {
  const d = new Date(dateStr || 0);
  return (now - d) / (1000 * 60 * 60);
}
function buildMsg(lead) {
  const nome = lead.nome && !['nao_informado','não informado'].includes(norm(lead.nome)) ? `${lead.nome.split(' ')[0]}, ` : '';
  const tipoImovel = lead.tipo_imovel && !['indefinido','nao_informado'].includes(norm(lead.tipo_imovel)) ? lead.tipo_imovel : '';
  const bairro = lead.bairro && !['indefinido','nao_informado'].includes(norm(lead.bairro)) ? lead.bairro : '';
  const cidade = lead.cidade || '';

  if (tipo === 'FOLLOWUP_2H') {
    if (tipoImovel || bairro || cidade) {
      return `${nome}conseguiu ver as opções${tipoImovel ? ' de ' + tipoImovel : ''}${bairro ? ' no ' + bairro : ''}${cidade ? ' em ' + cidade : ''}? Se quiser, posso te mostrar outras opções também 👌`;
    }
    return `${nome}${cfg.mensagem_2h_generica}`;
  }

  if (tipoImovel || bairro || cidade) {
    return `${nome}passando só pra saber se você ainda está procurando${tipoImovel ? ' ' + tipoImovel : ' imóvel'}${bairro ? ' no ' + bairro : ''}${cidade ? ' em ' + cidade : ''} ou se já resolveu 😊`;
  }
  return `${nome}${cfg.mensagem_24h_generica}`;
}

const currentHour = hourInTZ(cfg.timezone || 'America/Asuncion');
const start = Number(cfg.horario_inicio ?? 8);
const end = Number(cfg.horario_fim ?? 19);
if (currentHour < start || currentHour >= end) return [];

let leads = $input.all().flatMap(i => Array.isArray(i.json) ? i.json.map(x => ({ json: x })) : [i]);
const etapasBloqueadas = ['FINALIZADO','CORRETOR','ATENDIMENTO_MANUAL','NEGOCIACAO','NEGOCIAÇÃO','CLIENTE','DESCADASTRADO','SEM_INTERESSE'];

leads = leads
  .map(i => i.json)
  .filter(l => l && l.id && l.telefone)
  .filter(l => !l.optout)
  .filter(l => !l[flag])
  .filter(l => diffHours(l.updated_at) >= minHours)
  .filter(l => !l.ultimo_followup_em || diffHours(l.ultimo_followup_em) >= (tipo === 'FOLLOWUP_24H' ? 20 : 1.5))
  .filter(l => !etapasBloqueadas.includes(String(l.etapa_funil || '').toUpperCase()))
  .filter(l => !hasBlockWords(l))
  .slice(0, Number(cfg.max_envios_por_rodada || 8));

return leads.map((lead, index) => {
  const rand = Math.floor(Number(cfg.delay_min_segundos || 35) + Math.random() * (Number(cfg.delay_max_segundos || 95) - Number(cfg.delay_min_segundos || 35)));
  const delay = index * Number(cfg.intervalo_base_por_lead_segundos || 75) + rand;
  return {
    json: {
      ...lead,
      tipo_followup: tipo,
      mensagem_followup: buildMsg(lead),
      delay_segundos: delay,
      antiban_status: 'aprovado',
      antiban_motivo: `Dentro da janela, sem opt-out, etapa aberta, ${minHours}h+ sem atualização`,
      enviado_por: cfg.session
    }
  };
});

